mapper.select:
select NOTIFICATION_TYPE, listagg(EMAIL_ADDR, ',') within group ( order by 1) EMAIL_ADDRS from(
select EMAIL_ADDR, ${COLUMN_NAME} NOTIFICATION_TYPE  from nyehms_users where ${COLUMN_NAME}
 is not null and (end_Date is null or end_Date > SYSDATE) )  group by NOTIFICATION_TYPE

SELECT APP_NAME, APP_STAGE, URL_ACCESS_TOKEN, CLIENT_SECRET, ENDPOINTS 
FROM CODED_WEB_SERVICE_CONSTANTS 
WHERE APP_NAME = 'nyehms' and APP_STAGE = #{userStage} and ENDPOINTS like '%'||#{function}
